export default function App() {
  const [week, setWeek] = useState('current');
  const streak = selectWeeklyStreak(week);
  return (
    <main className="dashboard" data-week={week}>
      <header className="dashboard__header"><h1>Weekly workout streak</h1>
        <button type="button" onClick={() => setWeek('current')}>Current week</button>
      </header>
      <WeeklyStreakPanel streak={streak} week={week} />
    </main>
  );
}

