export const workoutTypes = ['run', 'lift', 'cycle', 'swim'];
export const defaultWorkoutState = { selectedWeek: 'current', workouts: [] };
export function completedWorkouts(workouts) {
  return workouts.filter((workout) => workout.completed);
}
export function weeklyWorkoutStreak(workouts, week = 'current') {
  return completedWorkouts(workouts).filter((workout) => workout.week === week).length;
}
export function replaceWorkout(state, workout) {
  return { ...state, workouts: [...state.workouts.filter((item) => item.id !== workout.id), workout] };
}

